import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"\d+(?:\.\d+)?"


def _finish(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(round(total))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("expected a string")

    stripped = text.strip()
    if not stripped:
        raise ValueError("empty input")

    # Bare non-negative integer (seconds).
    if re.fullmatch(r"\d+", stripped):
        return int(stripped)

    # Clock notation: hh:mm:ss or mm:ss.
    if ":" in stripped:
        parts = stripped.split(":")
        if len(parts) not in (2, 3):
            raise ValueError("invalid clock notation")
        for p in parts:
            if not re.fullmatch(_NUM, p):
                raise ValueError("invalid clock notation")
        nums = [float(p) for p in parts]
        if len(nums) == 2:
            mm, ss = nums
            total = mm * 60 + ss
        else:
            hh, mm, ss = nums
            total = hh * 3600 + mm * 60 + ss
        return _finish(total)

    # ISO 8601 durations.
    if stripped[0] in "Pp":
        pattern = re.compile(
            r"P(?:(%s)W)?(?:(%s)D)?(?:T(?:(%s)H)?(?:(%s)M)?(?:(%s)S)?)?" % (
                _NUM, _NUM, _NUM, _NUM, _NUM),
            re.IGNORECASE,
        )
        match = pattern.fullmatch(stripped)
        if not match or not any(match.groups()):
            raise ValueError("invalid ISO 8601 duration")
        weeks, days, hours, minutes, seconds = match.groups()
        total = 0.0
        if weeks:
            total += float(weeks) * 604800
        if days:
            total += float(days) * 86400
        if hours:
            total += float(hours) * 3600
        if minutes:
            total += float(minutes) * 60
        if seconds:
            total += float(seconds)
        return _finish(total)

    # Number+unit components, optionally separated by spaces.
    compact = re.sub(r"\s+", "", stripped).lower()
    token = re.compile(r"(%s)([a-z]+)" % _NUM)
    pos = 0
    total = 0.0
    found = False
    while pos < len(compact):
        m = token.match(compact, pos)
        if not m:
            raise ValueError("invalid duration")
        value, unit = m.group(1), m.group(2)
        if unit not in _UNITS:
            raise ValueError("unknown unit: %r" % unit)
        total += float(value) * _UNITS[unit]
        pos = m.end()
        found = True

    if not found:
        raise ValueError("invalid duration")
    return _finish(total)

